<template>
  <img
    :src="src"
    :srcset="srcset"
    :sizes="`${width}px`"
    :alt="alt"
    :height="height"
    :width="width"
    class="app-logo flex-grow-0 flex-shrink-0"
    draggable="false"
  />
</template>

<script>
// The scraperAI logo from public/brand/ (generated by design/brand/generate.py
// from the source PNGs next to it).
//   variant="mark"     the robot chat-bubble on its own, square, `size` px
//   variant="wordmark" robot + "scraperAI", `size` is the height; in dark
//                      theme the "scraper" letters switch to white
// Both are transparent, so don't wrap them in a coloured avatar.
const MARK = [64, 128, 192, 256, 512];
const WORD = [96, 192, 384];
const WORD_RATIO = 1802 / 453;

export default {
  name: "AppLogo",

  props: {
    size: { type: [Number, String], default: 36 },
    variant: {
      type: String,
      default: "mark",
      validator: (v) => ["mark", "wordmark"].includes(v),
    },
    alt: { type: String, default: "scraperAI" },
  },

  computed: {
    isWord() {
      return this.variant === "wordmark";
    },
    height() {
      return Number(this.size);
    },
    width() {
      return this.isWord
        ? Math.round(this.height * WORD_RATIO)
        : this.height;
    },
    base() {
      const dark = this.$vuetify && this.$vuetify.theme.dark;
      const name = this.isWord ? (dark ? "wordmark-dark" : "wordmark") : "mark";
      return `${process.env.BASE_URL}brand/${name}-`;
    },
    files() {
      return this.isWord ? WORD : MARK;
    },
    src() {
      const want = this.height * 2;
      const n = this.files.find((s) => s >= want) || this.files[this.files.length - 1];
      return `${this.base}${n}.png`;
    },
    srcset() {
      return this.files
        .map((n) => `${this.base}${n}.png ${this.isWord ? Math.round(n * WORD_RATIO) : n}w`)
        .join(", ");
    },
  },
};
</script>

<style scoped>
.app-logo {
  display: block;
  object-fit: contain;
  user-select: none;
}
</style>
